# standard imports
import unittest

# third party imports

# local imports
from njoy.dryad import InteractionType
from njoy.dryad.id import ElectronSubshellID
from njoy.dryad.id import LevelID
from njoy.dryad.id import ElementID
from njoy.dryad.id import ParticleID
from njoy.dryad.id import ReactionType

class Test_ReactionType( unittest.TestCase ) :
    """Unit test for the ReactionType class."""

    def test_values( self ) :

        g = ParticleID.photon()
        n = ParticleID.neutron()
        p = ParticleID.proton()
        d = ParticleID.deuteron()
        t = ParticleID.triton()
        h = ParticleID.helion()
        a = ParticleID.alpha()
        eminus = ParticleID.electron()
        eplus = ParticleID.positron()

        u = ParticleID( 'U' )
        u238 = ParticleID( 'U238' )
        u238_e2 = ParticleID( 'U238_e2' )

        nuclear = InteractionType.Nuclear
        atomic = InteractionType.Atomic

        empty = {}

        # special numbers
        id = ReactionType.total()
        self.assertEqual( 1, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'total', id.symbol )
        self.assertIsNone( id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( True, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType.total( InteractionType.Nuclear ) )
        self.assertEqual( id, ReactionType( 1 ) )
        self.assertEqual( id, ReactionType( 'total' ) )
        self.assertEqual( id, ReactionType( 'total[nuclear]' ) )
        with self.assertRaises( RuntimeError ) : id.resolve( n, u238 )

        id = ReactionType( 3 )
        self.assertEqual( 3, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'non-elastic', id.symbol )
        self.assertIsNone( id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( True, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'non-elastic' ) )
        with self.assertRaises( RuntimeError ) : id.resolve( n, u238 )

        id = ReactionType( 5 )
        self.assertEqual( 5, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'anything', id.symbol )
        self.assertIsNone( id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( True, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'anything' ) )
        with self.assertRaises( RuntimeError ) : id.resolve( n, u238 )

        id = ReactionType( 18 )
        self.assertEqual( 18, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'fission(t)', id.symbol )
        self.assertIsNone( id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( True, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'fission' ) )
        self.assertEqual( id, ReactionType( 'fission(t)' ) )
        with self.assertRaises( RuntimeError ) : id.resolve( n, u238 )

        id = ReactionType( 19 )
        self.assertEqual( 19, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'fission[first]', id.symbol )
        self.assertIsNone( id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( True, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'fission[first]' ) )
        self.assertEqual( id, ReactionType( 'fission1' ) )
        with self.assertRaises( RuntimeError ) : id.resolve( n, u238 )

        id = ReactionType( 20 )
        self.assertEqual( 20, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'fission[second]', id.symbol )
        self.assertIsNone( id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( True, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'fission[second]' ) )
        self.assertEqual( id, ReactionType( 'fission2' ) )
        with self.assertRaises( RuntimeError ) : id.resolve( n, u238 )

        id = ReactionType( 21 )
        self.assertEqual( 21, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'fission[third]', id.symbol )
        self.assertIsNone( id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( True, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'fission[third]' ) )
        self.assertEqual( id, ReactionType( 'fission3' ) )
        with self.assertRaises( RuntimeError ) : id.resolve( n, u238 )

        id = ReactionType( 38 )
        self.assertEqual( 38, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'fission[fourth]', id.symbol )
        self.assertIsNone( id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( True, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'fission[fourth]' ) )
        self.assertEqual( id, ReactionType( 'fission4' ) )
        with self.assertRaises( RuntimeError ) : id.resolve( n, u238 )

        id = ReactionType( 27 )
        self.assertEqual( 27, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'absorption', id.symbol )
        self.assertIsNone( id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( True, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'absorption' ) )
        with self.assertRaises( RuntimeError ) : id.resolve( n, u238 )

        id = ReactionType( 101 )
        self.assertEqual( 101, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'disappearance', id.symbol )
        self.assertIsNone( id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( True, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'disappearance' ) )
        with self.assertRaises( RuntimeError ) : id.resolve( n, u238 )

        # standard incident neutron and charged particle reaction types

        # elastic for a ground state target
        id = ReactionType.elastic( g )
        self.assertIsNone( id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'g(0)', id.symbol )
        self.assertEqual( empty, id.particles )
        self.assertEqual( 0, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( False, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( g, 2 ) )
        self.assertEqual( id, ReactionType( g, 2, 0 ) )
        self.assertEqual( id, ReactionType.elastic( g, 0 ) )
        self.assertEqual( id, ReactionType( empty, 0 ) )
        self.assertEqual( id, ReactionType( { g : 1 }, 0 ) )
        self.assertEqual( id, ReactionType( 'g(0)' ) )
        self.assertEqual( u238, id.resolve( g, u238 ) )

        id = ReactionType.elastic( n )
        self.assertEqual( 50, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'n(0)', id.symbol )
        self.assertEqual( { n : 1 }, id.particles )
        self.assertEqual( 0, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( n, 2 ) )
        self.assertEqual( id, ReactionType( n, 2, 0 ) )
        self.assertEqual( id, ReactionType.elastic( n, 0 ) )
        self.assertEqual( id, ReactionType( { n : 1 }, 0 ) )
        self.assertEqual( id, ReactionType( 'n(0)' ) )
        self.assertEqual( u238, id.resolve( n, u238 ) )

        id = ReactionType.elastic( p )
        self.assertEqual( 600, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'p(0)', id.symbol )
        self.assertEqual( { p : 1 }, id.particles )
        self.assertEqual( 0, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( p, 2 ) )
        self.assertEqual( id, ReactionType( p, 2, 0 ) )
        self.assertEqual( id, ReactionType.elastic( p, 0 ) )
        self.assertEqual( id, ReactionType( { p : 1 }, 0 ) )
        self.assertEqual( id, ReactionType( 'p(0)' ) )
        self.assertEqual( u238, id.resolve( p, u238 ) )

        id = ReactionType.elastic( d )
        self.assertEqual( 650, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'd(0)', id.symbol )
        self.assertEqual( { d : 1 }, id.particles )
        self.assertEqual( 0, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( d, 2 ) )
        self.assertEqual( id, ReactionType( d, 2, 0 ) )
        self.assertEqual( id, ReactionType.elastic( d, 0 ) )
        self.assertEqual( id, ReactionType( { d : 1 }, 0 ) )
        self.assertEqual( id, ReactionType( 'd(0)' ) )
        self.assertEqual( u238, id.resolve( d, u238 ) )

        id = ReactionType.elastic( t )
        self.assertEqual( 700, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 't(0)', id.symbol )
        self.assertEqual( { t : 1 }, id.particles )
        self.assertEqual( 0, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( t, 2 ) )
        self.assertEqual( id, ReactionType( t, 2, 0 ) )
        self.assertEqual( id, ReactionType.elastic( t, 0 ) )
        self.assertEqual( id, ReactionType( { t : 1 }, 0 ) )
        self.assertEqual( id, ReactionType( 't(0)' ) )
        self.assertEqual( u238, id.resolve( t, u238 ) )

        id = ReactionType.elastic( h )
        self.assertEqual( 750, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'h(0)', id.symbol )
        self.assertEqual( { h : 1 }, id.particles )
        self.assertEqual( 0, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( h, 2 ) )
        self.assertEqual( id, ReactionType( h, 2, 0 ) )
        self.assertEqual( id, ReactionType.elastic( h, 0 ) )
        self.assertEqual( id, ReactionType( { h : 1 }, 0 ) )
        self.assertEqual( id, ReactionType( 'h(0)' ) )
        self.assertEqual( u238, id.resolve( h, u238 ) )

        id = ReactionType.elastic( a )
        self.assertEqual( 800, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'a(0)', id.symbol )
        self.assertEqual( { a : 1 }, id.particles )
        self.assertEqual( 0, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( a, 2 ) )
        self.assertEqual( id, ReactionType( a, 2, 0 ) )
        self.assertEqual( id, ReactionType.elastic( a, 0 ) )
        self.assertEqual( id, ReactionType( { a : 1 }, 0 ) )
        self.assertEqual( id, ReactionType( 'a(0)' ) )
        self.assertEqual( u238, id.resolve( a, u238 ) )

        # elastic for an excited state target
        id = ReactionType.elastic( g, 2 )
        self.assertIsNone( id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'g(2)', id.symbol )
        self.assertEqual( empty, id.particles )
        self.assertEqual( 2, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( False, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( g, 2, 2 ) )
        self.assertEqual( id, ReactionType.elastic( g, 2 ) )
        self.assertEqual( id, ReactionType( empty, 2 ) )
        self.assertEqual( id, ReactionType( { g : 1 }, 2 ) )
        self.assertEqual( id, ReactionType( 'g(2)' ) )
        self.assertEqual( u238_e2, id.resolve( g, u238_e2 ) )

        id = ReactionType.elastic( n, 2 )
        self.assertEqual( 52, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'n(2)', id.symbol )
        self.assertEqual( { n : 1 }, id.particles )
        self.assertEqual( 2, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( n, 2, 2 ) )
        self.assertEqual( id, ReactionType.elastic( n, 2 ) )
        self.assertEqual( id, ReactionType( { n : 1 }, 2 ) )
        self.assertEqual( id, ReactionType( 'n(2)' ) )
        self.assertEqual( u238_e2, id.resolve( n, u238_e2 ) )

        id = ReactionType.elastic( p, 2 )
        self.assertEqual( 602, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'p(2)', id.symbol )
        self.assertEqual( { p : 1 }, id.particles )
        self.assertEqual( 2, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( p, 2, 2 ) )
        self.assertEqual( id, ReactionType.elastic( p, 2 ) )
        self.assertEqual( id, ReactionType( { p : 1 }, 2 ) )
        self.assertEqual( id, ReactionType( 'p(2)' ) )
        self.assertEqual( u238_e2, id.resolve( p, u238_e2 ) )

        id = ReactionType.elastic( d, 2 )
        self.assertEqual( 652, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'd(2)', id.symbol )
        self.assertEqual( { d : 1 }, id.particles )
        self.assertEqual( 2, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( d, 2, 2 ) )
        self.assertEqual( id, ReactionType.elastic( d, 2 ) )
        self.assertEqual( id, ReactionType( { d : 1 }, 2 ) )
        self.assertEqual( id, ReactionType( 'd(2)' ) )
        self.assertEqual( u238_e2, id.resolve( d, u238_e2 ) )

        id = ReactionType.elastic( t, 2 )
        self.assertEqual( 702, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 't(2)', id.symbol )
        self.assertEqual( { t : 1 }, id.particles )
        self.assertEqual( 2, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( t, 2, 2 ) )
        self.assertEqual( id, ReactionType.elastic( t, 2 ) )
        self.assertEqual( id, ReactionType( { t : 1 }, 2 ) )
        self.assertEqual( id, ReactionType( 't(2)' ) )
        self.assertEqual( u238_e2, id.resolve( t, u238_e2 ) )

        id = ReactionType.elastic( h, 2 )
        self.assertEqual( 752, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'h(2)', id.symbol )
        self.assertEqual( { h : 1 }, id.particles )
        self.assertEqual( 2, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( h, 2, 2 ) )
        self.assertEqual( id, ReactionType.elastic( h, 2 ) )
        self.assertEqual( id, ReactionType( { h : 1 }, 2 ) )
        self.assertEqual( id, ReactionType( 'h(2)' ) )
        self.assertEqual( u238_e2, id.resolve( h, u238_e2 ) )

        id = ReactionType.elastic( a, 2 )
        self.assertEqual( 802, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'a(2)', id.symbol )
        self.assertEqual( { a : 1 }, id.particles )
        self.assertEqual( 2, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( a, 2, 2 ) )
        self.assertEqual( id, ReactionType.elastic( a, 2 ) )
        self.assertEqual( id, ReactionType( { a : 1 }, 2 ) )
        self.assertEqual( id, ReactionType( 'a(2)' ) )
        self.assertEqual( u238_e2, id.resolve( a, u238_e2 ) )

        # tests for other reaction types
        id = ReactionType( 4 )
        self.assertEqual( 4, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'n(t)', id.symbol )
        self.assertEqual( { n : 1 }, id.particles )
        self.assertEqual( LevelID.all, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( { n : 1 }, LevelID.all ) )
        self.assertEqual( id, ReactionType( 'n' ) )
        self.assertEqual( id, ReactionType( 'n(t)' ) )
        self.assertEqual( ParticleID( 'U238[all]' ), id.resolve( n, u238 ) )

        id = ReactionType( 91 )
        self.assertEqual( 91, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( 'n(c)', id.symbol )
        self.assertEqual( { n : 1 }, id.particles )
        self.assertEqual( LevelID.continuum, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( { n : 1 }, LevelID.continuum ) )
        self.assertEqual( id, ReactionType( 'n(c)' ) )
        self.assertEqual( ParticleID( 'U238[continuum]' ), id.resolve( n, u238 ) )

        id = ReactionType( 875 )
        self.assertEqual( 875, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( '2n(0)', id.symbol )
        self.assertEqual( { n : 2 }, id.particles )
        self.assertEqual( 0, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( { n : 2 }, 0 ) )
        self.assertEqual( id, ReactionType( '2n(0)' ) )
        self.assertEqual( ParticleID( 'U237' ), id.resolve( n, u238 ) )

        id = ReactionType( 199 )
        self.assertEqual( 199, id.mt )
        self.assertEqual( nuclear, id.interaction_type )
        self.assertEqual( '3n2pa(t)', id.symbol )
        self.assertEqual( { n : 3, p : 2, a : 1 }, id.particles )
        self.assertEqual( LevelID.all, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( { n : 3, p : 2, a : 1 }, LevelID.all ) )
        self.assertEqual( id, ReactionType( '3n2pa(t)' ) )
        self.assertEqual( ParticleID( 'Ra230[all]' ), id.resolve( n, u238 ) )

        # photoatomic and electroatomic reaction types
        id = ReactionType.total( InteractionType.Atomic )
        self.assertEqual( 501, id.mt )
        self.assertEqual( atomic, id.interaction_type )
        self.assertEqual( 'total[atomic]', id.symbol )
        self.assertIsNone( id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( True, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 501 ) )
        self.assertEqual( id, ReactionType( 'total[atomic]' ) )
        with self.assertRaises( RuntimeError ) : id.resolve( g, u )

        id = ReactionType( 502 )
        self.assertEqual( 502, id.mt )
        self.assertEqual( atomic, id.interaction_type )
        self.assertEqual( 'coherent', id.symbol )
        self.assertEqual( empty, id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'coherent' ) )
        self.assertEqual( u, id.resolve( g, u ) )

        id = ReactionType( 504 )
        self.assertEqual( 504, id.mt )
        self.assertEqual( atomic, id.interaction_type )
        self.assertEqual( 'incoherent', id.symbol )
        self.assertEqual( empty, id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'incoherent' ) )
        self.assertEqual( u, id.resolve( g, u ) )

        id = ReactionType( 'deficit-scattering' ) # no mt number for this
        self.assertIsNone( id.mt )
        self.assertEqual( atomic, id.interaction_type )
        self.assertEqual( 'deficit-scattering', id.symbol )
        self.assertEqual( { eminus : 1 } , id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( False, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'e-[deficit-scattering]' ) )
        self.assertEqual( u, id.resolve( g, u ) )

        id = ReactionType( 525 )
        self.assertEqual( 525, id.mt )
        self.assertEqual( atomic, id.interaction_type )
        self.assertEqual( 'large-angle-scattering', id.symbol )
        self.assertEqual( { eminus : 1 } , id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'e-[large-angle-scattering]' ) )
        self.assertEqual( id, ReactionType( 'large-angle-scattering' ) )
        self.assertEqual( u, id.resolve( g, u ) )

        id = ReactionType( 515 )
        self.assertEqual( 515, id.mt )
        self.assertEqual( atomic, id.interaction_type )
        self.assertEqual( 'pair-production-electron', id.symbol )
        self.assertEqual( { eminus : 2, eplus : 1 }, id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( '2e-e+' ) )
        self.assertEqual( id, ReactionType( '2e-,e+' ) )
        self.assertEqual( id, ReactionType( 'pair-production-electron' ) )
        self.assertEqual( u, id.resolve( g, u ) )

        id = ReactionType( 517 )
        self.assertEqual( 517, id.mt )
        self.assertEqual( atomic, id.interaction_type )
        self.assertEqual( 'pair-production-nuclear', id.symbol )
        self.assertEqual( { eminus : 1, eplus : 1 }, id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'e-e+' ) )
        self.assertEqual( id, ReactionType( 'e-,e+' ) )
        self.assertEqual( id, ReactionType( 'pair-production-nuclear' ) )
        self.assertEqual( u, id.resolve( g, u ) )

        id = ReactionType( 516 )
        self.assertEqual( 516, id.mt )
        self.assertEqual( atomic, id.interaction_type )
        self.assertEqual( 'pair-production', id.symbol )
        self.assertIsNone( id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( True, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'pair-production' ) )
        with self.assertRaises( RuntimeError ) : id.resolve( g, u )

        id = ReactionType( 527 )
        self.assertEqual( 527, id.mt )
        self.assertEqual( atomic, id.interaction_type )
        self.assertEqual( 'bremsstrahlung', id.symbol )
        self.assertEqual( { eminus : 1 } , id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'e-[bremsstrahlung]' ) )
        self.assertEqual( id, ReactionType( 'bremsstrahlung' ) )
        self.assertEqual( u, id.resolve( g, u ) )

        id = ReactionType( 528 )
        self.assertEqual( 528, id.mt )
        self.assertEqual( atomic, id.interaction_type )
        self.assertEqual( 'excitation', id.symbol )
        self.assertEqual( { eminus : 1 } , id.particles )
        self.assertIsNone( id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
        self.assertEqual( id, ReactionType( 'e-[excitation]' ) )
        self.assertEqual( id, ReactionType( 'excitation' ) )
        self.assertEqual( u, id.resolve( g, u ) )

        id = ReactionType( g, 534 )
        self.assertEqual( 534, id.mt )
        self.assertEqual( atomic, id.interaction_type )
        self.assertEqual( 'photo-ionisation{1s1/2}', id.symbol )
        self.assertEqual( { eminus : 1 } , id.particles )
        self.assertEqual( ElectronSubshellID.K, id.level )
        self.assertEqual( False, id.is_special )
        self.assertEqual( True, id.is_compatible_with_endf )
