        a = ParticleID.alpha()
        eminus = ParticleID.electron()
        eplus = ParticleID.positron()

        u = ParticleID( 'U' )
        u238 = ParticleID( 'U238' )

        # resolve gamma induced reactions
        self.assertEqual( ParticleID( "U238_e0" ), ReactionType(  "g(0)" ).resolve( g, u238 ) )
